UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 51, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 52, 7, NULL::text),(3, 180, 40, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 224, 965, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='0e682c4f-4ddb-54b7-9a2f-c08ce1580062' AND md5(a.contenido)='af29142572e73494195bebd781f36e6f' RETURNING a.id,md5(a.contenido) hash;